import test from 'node:test';import assert from 'node:assert/strict';import * as O from '../src/optics.mjs';
import {createLinearBuffer,renderStars,encodeFrame} from '../src/renderer.mjs';
const total=(b,k)=>b.reduce((s,v,i)=>s+(i%3===k?v:0),0),near=(a,b,t=3e-6)=>assert.ok(Math.abs(a-b)<t,`${a} != ${b}`);
test('CP5 optical API exists',()=>assert.equal(typeof O.psfComponents,'function'));
test('every optical preset redistributes rather than creates flux',()=>{for(const preset of ['reference','camera','eye'])for(const wavelengthNm of [420,550,680]){const a=O.psfComponents({preset,wavelengthNm,arcsecPerCssPixel:3});near(a.reduce((s,v)=>s+v.weight,0),1);assert.ok(a.every(v=>v.weight>=0&&v.sigmaCss>0));}});
test('wavelength-dependent diffraction is explicit, not bright-star class',()=>{const a=O.psfComponents({preset:'camera',wavelengthNm:420,arcsecPerCssPixel:.3}),b=O.psfComponents({preset:'camera',wavelengthNm:680,arcsecPerCssPixel:.3});assert.ok(b[0].sigmaCss>a[0].sigmaCss);});
test('invalid optics fail instead of silently creating huge or negative kernels',()=>{assert.throws(()=>O.psfComponents({preset:'fictional'}));assert.throws(()=>O.psfComponents({apertureMm:0}));assert.throws(()=>O.psfComponents({scatterFraction:2}));});
test('new optical renderer preserves flux across subpixel positions and DPR',()=>{for(const opticalPreset of ['reference','camera','eye'])for(const dpr of [1,1.37,2,3])for(const off of [0,.2,.7]){const r=renderStars([{x:30+off,y:30.3,altDeg:90,vmag:0,bv:0}],{width:62,height:62,dpr,opticalPreset,fluxAt:()=>({rgb:[1,2,3],colourFallback:false}),atmosphere:{}});for(let k=0;k<3;k++)near(total(r.linear,k)/dpr**2,k+1,8e-6);}});
test('close pair is sum of two sources, not distance-rescaled/deduplicated light',()=>{const a={x:20,y:20,altDeg:50,vmag:0,bv:0},b={...a,x:20.1};const opts={width:44,height:44,fluxAt:()=>({rgb:[1,1,1]}),opticalPreset:'reference'};near(total(renderStars([a,b],opts).linear,0),2*total(renderStars([a],opts).linear,0));});
test('border crops flux without renormalising a PSF fragment',()=>{const r=renderStars([{x:0,y:30,altDeg:60,vmag:0,bv:0}],{width:60,height:60,opticalPreset:'reference',fluxAt:()=>({rgb:[1,1,1]})});near(total(r.linear,0),.5);});
test('display saturation is bounded and monotone, linear buffer is unclipped',()=>{const a=renderStars([{x:10.5,y:10.5,altDeg:60,vmag:0,bv:0}],{width:22,height:22,fluxAt:()=>({rgb:[10000,20000,30000]})});assert.ok(Math.max(...a.linear)>1);const b=encodeFrame(a.linear,100);assert.ok(b.every(Number.isFinite));assert.equal(Math.max(...b),255);});
